{"content":"#!/usr/bin/env python3
"""Generate /testbed/revocation_report.json from checker output (helper only, not part of repo)."""
import json
import subprocess

# Run the checker to get live status
out = subprocess.run(
    ["python3", "/testbed/check_revocation.py"],
    capture_output=True, text=True, check=True
).stdout
data = json.loads(out)

# Load employee names from CSV
names = {}
with open("/testbed/data/offboarding_list.csv") as f:
    next(f)
    for line in f:
        line = line.strip()
        if line:
            parts = line.split(",")
            names[parts[0].strip()] = parts[1].strip()

PRIV_NAMES = {"vpn": "VPN Access", "gitlab": "GitLab Access", "wiki": "Internal Wiki Access"}

report = {
    "report_metadata": {
        "audit_timestamp": data["timestamp"],
        "auditor": "pi coding agent (automated audit)",
        "report_version": "1.0"
    },
    "summary": {
        "total_employees_checked": 0,
        "total_privileges_checked": 0,
        "successfully_revoked_count": 0,
        "all_privileges_revoked": None
    },
    "employee_details": [],
    "findings": {
        "employees_notfully_revoked": []
    },
    "conclusion": ""
}

# Group privileges by employee, preserving checker order
by_emp = {}
order = []
for p in data["privileges"]:
    if p["employee_id"] not in by_emp:
        by_emp[p["employee_id"]] = []
        order.append(p["employee_id"])
    by_emp[p["employee_id"]].append(p)

revoked_total = 0
notfully = []

for emp_id in order:
    privs = []
    emp_all_revoked = True
    for p in privs:
        is_revoked = (p["status"] == "revoked")
        if is_revoked:
            revoked_total += 1
        else:
            emp_all_revoked = False
        privs.append({
            "privilege_name": PRIV_NAMES[p["system"]],
            "system": p["system"],
            "privilege_revoked": is_revoked
        })
    if not emp_all_revoked:
        notfully.append(emp_id)
    report["employee_details"].append({
        "employee_id": emp_id,
        "employee_name": names[emp_id],
        "privileges": privs,
        "all_privileges_revoked": emp_all_revoked
    })

report["summary"]["total_employees_checked"] = len(order)
report["summary"]["total_privileges_checked"] = data["total_privileges"]
report["summary"]["successfully_revoked_count"] = revoked_total
report["summary"]["all_privileges_revoked"] = (len(notfully) == 0)
report["findings"]["employees_notfully_revoked"] = sorted(set(notfully))

report["conclusion"] = (
    "Audit result: privileges still not revoked. Of the 30 privileges checked for the 10 "
    "offboarded employees, 28 have been successfully revoked (status 'revoked'), while 2 "
    "remain not revoked: emp_008 (Henry Yang) VPN access is still active, and emp_009 "
    "(Iris Huang) GitLab access is only in 'scheduled' status and not yet actually revoked. "
    "Immediate manual revocation of these 2 privileges is required."
)

with open("/testbed/revocation_report.json", "w") as f:
    json.dump(report, f, indent=2)
    f.write("\n")

print("Report written to /testbed/revocation_report.json")
","path":"/tmp/gen_report.py"}

